#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Benchline go-live runner: the remaining Go-live blockers, one fresh Claude
# Code session per ticket (the /clear between tickets), each followed by the
# build, test and format gates, a push and the issue's closing. Then the
# leftovers from #72/#73. Tickets already closed are skipped, so it can be
# re-run after stopping.
#
#   scripts/go-live.sh

TOTAL_STAGES=16

cd "$(dirname "$0")/.."
LOGS=$(mktemp -d "${TMPDIR:-/tmp}/benchline-go-live.XXXXXX")
DONE=()

issue_state() { gh issue view "$1" --json state --jq .state; }
issue_title() { gh issue view "$1" --json title --jq .title; }

# heading "Name" reprints the current stage after a Claude session has used
# the screen, without advancing progress.
heading() {
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# require_clean waits until the working tree has no uncommitted changes.
require_clean() {
  while [[ -n "$(git status --porcelain)" ]]; do
    warn "The working tree has uncommitted changes:"
    git status --short | sed 's/^/    /'
    confirm "Commit or stash them in another terminal, then check again?" \
      || { warn "Stopped. Re-run scripts/go-live.sh once the tree is clean."; exit 1; }
  done
}

# gate "name" command... runs one check quietly, showing its tail on failure.
gate() {
  local name="$1"; shift
  local log="$LOGS/${name//[ :]/-}.log"
  printf '  %s…%s %s ' "$DIM" "$RESET" "$name"
  if "$@" >"$log" 2>&1; then
    printf '%s✓%s\n' "$GREEN" "$RESET"
    return 0
  fi
  printf '%s✗%s\n' "$RED" "$RESET"
  tail -n 15 "$log" | sed 's/^/    /'
  note "full log: $log"
  return 1
}

# gates runs every check the coding standards require before committing.
gates() {
  local failed=0
  gate "npm run build" npm run build || failed=1
  gate "npm test" npm test || failed=1
  gate "npm run format:check" npm run format:check || failed=1
  return "$failed"
}

# push_main offers to push commits origin/main doesn't have yet.
push_main() {
  git fetch -q origin main
  local ahead
  ahead=$(git rev-list --count origin/main..HEAD)
  if (( ahead == 0 )); then
    note "Nothing to push: origin/main is up to date."
    return
  fi
  say "Not yet on origin/main:"
  git log --oneline origin/main..HEAD | sed 's/^/    /'
  if confirm "Push $ahead commit(s) to origin main?"; then
    git push origin main || { warn "Push failed."; SKIPPED+=("push to origin main"); }
  else
    SKIPPED+=("push to origin main")
  fi
}

# work_ticket N runs one ticket: a fresh Claude session on /implement #N,
# then checks, push and closing. Repeats with a fresh session until done or
# the human stops.
work_ticket() {
  local n="$1" title before prompt problem shas comment
  title=$(issue_title "$n")
  stage "#$n · $title"
  if [[ "$(issue_state "$n")" == CLOSED ]]; then
    note "#$n is already closed, so it is skipped."
    DONE+=("#$n (already closed)")
    pause "Press Enter for the next stage"
    return
  fi
  require_clean
  say "A new Claude Code session starts with an empty context and runs /implement #$n."
  step "It reads the ticket, consults the regulatory guidance where needed, builds test-first and runs /code-review."
  step "Answer its questions, and let it commit to main."
  step "When it has committed, type /exit. Ending the session is the /clear between tickets."
  note "https://github.com/zhipengzhu1-dotcom/13-Sep-2026-LIMS/issues/$n"
  if ! confirm "Start the session for #$n now?"; then
    SKIPPED+=("#$n: not started")
    return
  fi

  before=$(git rev-parse HEAD)
  prompt="/implement #$n"
  while true; do
    claude "$prompt" || warn "The Claude session ended with an error."
    heading "#$n · checks"
    problem=""
    if [[ -z "$(git log --oneline "$before"..HEAD)" ]]; then
      problem="there is no new commit for #$n"
    elif [[ -n "$(git status --porcelain)" ]]; then
      git status --short | sed 's/^/    /'
      problem="changes were left uncommitted"
    else
      say "New commits:"
      git log --oneline "$before"..HEAD | sed 's/^/    /'
      gates || problem="the build, tests or format check failed (logs in $LOGS)"
    fi
    [[ -z "$problem" ]] && break
    warn "#$n is not finished: $problem."
    if confirm "Start another fresh session to finish it?"; then
      prompt="#$n is not finished: $problem. Finish it, make npm run build, npm test and npm run format:check pass, and commit to main."
    else
      SKIPPED+=("#$n: $problem")
      pause "Press Enter for the next stage"
      return
    fi
  done

  push_main

  if [[ "$(issue_state "$n")" == OPEN ]]; then
    shas=$(git log --reverse --format=%h "$before"..HEAD | paste -sd, - | sed 's/,/, /g')
    comment="Done in $shas. npm run build, npm test and npm run format:check pass."
    say "Closing comment: $comment"
    ask CLOSE_COMMENT "Type a different comment, or press Enter to use this one:"
    [[ -n "$CLOSE_COMMENT" ]] && comment="$CLOSE_COMMENT"
    if confirm "Close #$n?"; then
      gh issue close "$n" --comment "$comment" >/dev/null
      printf '  %s✓ closed%s #%s\n' "$GREEN" "$RESET" "$n"
    else
      SKIPPED+=("#$n: close the issue")
    fi
  else
    note "#$n was already closed by the session."
  fi
  DONE+=("#$n")
  pause "#$n is done. Press Enter; the next ticket starts in a new session."
}

# file_issue "title" "body" creates an issue for triage unless one with the
# same title exists.
file_issue() {
  local title="$1" body="$2" existing
  existing=$(gh issue list --state all --search "\"$title\" in:title" --json number,title \
    --jq ".[] | select(.title == \"$title\") | .number" | head -n1)
  say "$title"
  if [[ -n "$existing" ]]; then
    note "Already filed as #$existing."
    return
  fi
  if confirm "File it, labelled needs-triage?"; then
    gh issue create --title "$title" --body "$body" --label needs-triage | sed 's/^/    /'
    DONE+=("filed: $title")
  else
    SKIPPED+=("file issue: $title")
  fi
}

banner "Benchline go-live runner"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
for tool in git gh npm claude; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not installed."; exit 1; }
done
gh auth status >/dev/null 2>&1 || { warn "gh is not signed in. Run: gh auth login"; exit 1; }
branch=$(git branch --show-current)
if [[ "$branch" != main ]]; then
  warn "You are on $branch, and the agreed workflow commits to main. Run: git switch main"
  exit 1
fi
require_clean
git fetch -q origin main
behind=$(git rev-list --count HEAD..origin/main)
if (( behind > 0 )) && confirm "main is $behind commit(s) behind origin. Pull with --ff-only?"; then
  git pull --ff-only origin main
fi
push_main
say "Open Go-live blockers:"
gh issue list --label go-live-blocker --state open --json number,title \
  --jq '.[] | "#\(.number) \(.title)"' | sed 's/^/    /'
note "Order: #30 #54 #57 #38 #41 #42 #31, then #66 #61 #65 #67 in the order you choose."
pause

# ── 2–8 ───────────────────────────────────────────────────────────────────
for n in 30 54 57 38 41 42 31; do
  work_ticket "$n"
done

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Order the remaining Go-live blockers"
for n in 66 61 65 67; do
  say "#$n [$(issue_state "$n")] $(issue_title "$n")"
done
note "Suggested: #66 first, since #30's first-account command is its first step."
note "The others have no agreed order yet; that is your call."
while true; do
  ask BLOCKER_ORDER "Order, space-separated [66 61 65 67]:"
  BLOCKER_ORDER=${BLOCKER_ORDER//[#,]/ }
  [[ -z "${BLOCKER_ORDER// /}" ]] && BLOCKER_ORDER="66 61 65 67"
  # Word splitting is intended: one ticket number per word.
  # shellcheck disable=SC2086
  sorted=$(printf '%s\n' $BLOCKER_ORDER | sort -n | paste -sd' ' -)
  [[ "$sorted" == "61 65 66 67" ]] && break
  warn "Give each of 66, 61, 65 and 67 exactly once."
done
read -r -a BLOCKERS <<<"$BLOCKER_ORDER"

# ── 10–13 ─────────────────────────────────────────────────────────────────
for n in "${BLOCKERS[@]}"; do
  work_ticket "$n"
done

# ── 14 ────────────────────────────────────────────────────────────────────
stage "File the leftovers from #72/#73"
read -r -d '' REPLACE_BODY <<'EOF' || true
**Category:** bug. Found on 2026-09-14 while building #72 and #73.

**Current behavior:**
`signatures`, `audit`, `attachments`, `certificates`, `publications` and `acceptableIntakes` refuse UPDATE and DELETE (#62). But `INSERT OR REPLACE` with a key that already exists deletes the old row without firing its delete trigger, because SQLite skips delete triggers during REPLACE unless `recursive_triggers` is on. It then inserts the new content.

Reproduced on a seeded database: `INSERT OR REPLACE ... SELECT rowid, ... FROM <table> LIMIT 1`, with one column set to `'TAMPERED'`, rewrote one row in each of the six tables. Row counts stayed the same and no error was raised. Rewritten columns included `signatures.sampleId`, `certificates.approvedAt` and `acceptableIntakes.analyteId`.

`commands` and `commandReplays` already guard against this with BEFORE INSERT triggers (356cec0).

**Desired behavior:**
- A BEFORE INSERT trigger on each of the six tables refuses an insert whose key already exists, with that table's existing message. Ordinary appends are unchanged.
- The triggers reach existing database files as the next migration, and a new database gets the same triggers. `rehearseMigration` on a seeded database passes.

**Acceptance criteria:**
- [ ] The protected-table test also tries `INSERT OR REPLACE` on every protected table, and asserts the refusal and unchanged records.
- [ ] A migration test: a database from before the migration refuses replacing inserts afterwards and keeps every record.
- [ ] Following `docs/agents/regulatory.md`, checked against the electronic-records guidance (§11.10(e)) before building.

**Disposition:** for the maintainer to decide whether this joins the Go-live release, as #72 and #73 did.
EOF
read -r -d '' REHEARSAL_BODY <<'EOF' || true
**Category:** bug. Found on 2026-09-14 while reviewing #72 and #73.

**Current behavior:**
`rehearseMigration` checks that a migrated schema matches a new database's through `schemaOf` in `server/migrations.ts`. That describes each trigger by name only. The stores create triggers with `CREATE TRIGGER IF NOT EXISTS`, so if a store's trigger SQL changes (a new WHEN clause, say), a migrated database keeps the old definition while a new one gets the new definition, and the rehearsal still passes. The rehearsal is change-control evidence before a release.

**Desired behavior:**
- The rehearsal compares each trigger's whitespace-normalised definition, as `triggerDefinitions` already reads it, and reports a difference as schema drift.

**Acceptance criteria:**
- [ ] A rehearsal fails when a migrated database keeps an older definition of a trigger that a new database creates differently, and it names the trigger.
- [ ] The existing rehearsal tests pass unchanged.
EOF
read -r -d '' LIMIT_COMMENT <<'EOF' || true
Known limit to record in the validation evidence, from the regulatory check on #72 and #73 (§11.10(a)):

The protection triggers on applied commands and command replays (migration version 20, 356cec0) prevent changes from then on. They do not detect command records altered before migration 20 reached a database, or altered while a trigger was dropped. The audit trail tables have the same limit. Detecting earlier tampering was out of scope for #73.
EOF
file_issue "A replacing insert rewrites protected records despite their triggers" "$REPLACE_BODY"
printf '\n'
file_issue "Migration rehearsal does not compare trigger definitions" "$REHEARSAL_BODY"
printf '\n'
say "Known limit: command records altered before migration 20 are not detected."
if gh issue view 46 --json comments --jq '.comments[].body' | grep -q "altered before migration 20"; then
  note "Already recorded on #46."
elif confirm "Add it as a comment on #46 (validation of changes after go-live)?"; then
  gh issue comment 46 --body "$LIMIT_COMMENT" | sed 's/^/    /'
  DONE+=("known limit recorded on #46")
else
  SKIPPED+=("record the pre-migration tampering limit on #46")
fi
pause

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Rehearse migration 20 on a copy of a real database"
say "The rehearsal copies the database, migrates the copy, and checks row counts,"
say "every Electronic signature, Certificate of Analysis and attachment hash,"
say "and that the schema matches a new database. The original is only read."
note "It needs a database still at schema version 19, such as a backup from before this build."
ask REHEARSAL_DATABASE "Database file [data/prototype.sqlite]:"
REHEARSAL_DATABASE=${REHEARSAL_DATABASE:-data/prototype.sqlite}
if [[ ! -f "$REHEARSAL_DATABASE" ]]; then
  warn "No file at $REHEARSAL_DATABASE."
  SKIPPED+=("rehearse migration 20 (no database at $REHEARSAL_DATABASE)")
else
  mkdir -p data/rehearsals
  report="data/rehearsals/migration-20-$(date +%Y%m%d-%H%M%S).log"
  if npm run --silent rehearse-migration -- "$REHEARSAL_DATABASE" 2>&1 | tee "$report"; then
    printf '  %s✓ report saved%s %s\n' "$GREEN" "$RESET" "$report"
    note "Keep it with the release record for change control."
    DONE+=("rehearsal report: $report")
  else
    warn "The rehearsal did not pass. The report is in $report."
    SKIPPED+=("rehearse migration 20: see $report")
  fi
fi
pause

# ── 16 ────────────────────────────────────────────────────────────────────
stage "Optional: architecture review"
say "A new Claude Code session runs /improve-codebase-architecture to find deepening opportunities."
note "Known candidates: move the command key claim, replay and triggers out of laboratory.ts"
note "into their own module, and share the receipt fixtures between the two test files."
step "Pick one to take into /grill-with-docs, or none. Type /exit when done."
if confirm "Start the architecture review session?"; then
  claude "/improve-codebase-architecture"
  DONE+=("architecture review")
else
  SKIPPED+=("architecture review (optional)")
fi

finish
if (( ${#DONE[@]} )); then
  note "done this run:"
  for d in "${DONE[@]}"; do note "  - $d"; done
  printf '\n'
fi
